effect.shader:
//////////////////////////
vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy
// Effective quadrant radius cap. 9x9 taps per quadrant (324 fetches) is already
// a dense estimate of the quadrant mean/variance; the sample STRIDE is scaled by
// RADIUSS/radius so the kernel still spans exactly RADIUSS source pixels.
const int KMAX = 8;
//////////////////////////
    void main() {

    // ---- PASS 0 : Kuwahara rendered into the downsample="2" buffer -------------
    // The Kuwahara output is piecewise flat by construction, so evaluating it on a
    // half-res grid and bilinearly upsampling it costs 1/4 of the fragments.
    if( acPass == 0 ) {

        highp vec2 uv = acScreenNorm.st;
        // Step of ONE FULL-RES SOURCE PIXEL (taken from the content texture, not the
        // render target, so the kernel extent does not change in the half-res pass).
        highp vec2 src_size = 1.0 / max(getTexSize(inputImg.size), vec2(1.0));

        highp float fRad   = float(RADIUSS);
        int   radius       = int(min(fRad, float(KMAX)));
        highp float stride = (radius > 0) ? (fRad / float(radius)) : 1.0;
        highp float n      = float((radius + 1) * (radius + 1));

        vec3 m0 = vec3(0.0); vec3 m1 = vec3(0.0); vec3 m2 = vec3(0.0); vec3 m3 = vec3(0.0);
        vec3 s0 = vec3(0.0); vec3 s1 = vec3(0.0); vec3 s2 = vec3(0.0); vec3 s3 = vec3(0.0);
        vec3 c;

        // The four quadrants share the same |i|,|j| grid, so one double loop feeds all
        // four accumulators: the row offset is hoisted and each tap position is built once.
        for (int j = 0; j <= KMAX; ++j) {
            if (j > radius) break;
            highp float fj = float(j) * stride;
            for (int i = 0; i <= KMAX; ++i) {
                if (i > radius) break;
                highp float fi = float(i) * stride;
                c = texture2DCv(inputImg.texture, uv + vec2(-fi,-fj) * src_size).rgb; m0 += c; s0 += c * c;
                c = texture2DCv(inputImg.texture, uv + vec2( fi,-fj) * src_size).rgb; m1 += c; s1 += c * c;
                c = texture2DCv(inputImg.texture, uv + vec2( fi, fj) * src_size).rgb; m2 += c; s2 += c * c;
                c = texture2DCv(inputImg.texture, uv + vec2(-fi, fj) * src_size).rgb; m3 += c; s3 += c * c;
            }
        }

        vec4  fragColor  = vec4(0.0, 0.0, 0.0, 1.0);
        float min_sigma2 = 1e+2;

        m0 /= n;
        s0 = abs(s0 / n - m0 * m0);
        float sigma2 = s0.r + s0.g + s0.b;
        if (sigma2 < min_sigma2) {
            min_sigma2 = sigma2;
            fragColor = vec4(m0, 1.0);
        }

        m1 /= n;
        s1 = abs(s1 / n - m1 * m1);
        sigma2 = s1.r + s1.g + s1.b;
        if (sigma2 < min_sigma2) {
            min_sigma2 = sigma2;
            fragColor = vec4(m1, 1.0);
        }

        m2 /= n;
        s2 = abs(s2 / n - m2 * m2);
        sigma2 = s2.r + s2.g + s2.b;
        if (sigma2 < min_sigma2) {
            min_sigma2 = sigma2;
            fragColor = vec4(m2, 1.0);
        }

        m3 /= n;
        s3 = abs(s3 / n - m3 * m3);
        sigma2 = s3.r + s3.g + s3.b;
        if (sigma2 < min_sigma2) {
            min_sigma2 = sigma2;
            fragColor = vec4(m3, 1.0);
        }

        gl_FragColor = fragColor;
        return;
    }

    // ---- FINAL PASS : composite the (upsampled) painterly buffer at full res ----
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 factor   = texture2DCv(xcipher.texture,acScreenNorm.st);

    gl_FragColor = mix(texColor, factor, alpha) * texColor.a;
    }
